import os
import pandas as pd
import numpy as np
from datetime import datetime, timedelta

class DatasetLoader:
    """
    Handles loading, parsing, and multi-domain enrichment for recommendation engine training.
    Ingests real public datasets and generates domain-specific catalogs and interaction histories for:
    1. Aura Threads (Clothing & Fashion) — 35 Products
    2. Nexus Marketplace (General E-Commerce & Electronics) — 35 Products
    3. FreshPantry Superstore (Grocery & Fresh Milk) — 35 Products
    4. SavorCraft Artisanal Foods (Pickles & Regional Delicacies) — 30 Products
    Total Catalog Size: 135 Products (₹ INR Pricing)
    """

    def __init__(self, data_dir="dataset"):
        self.data_dir = data_dir
        self.raw_retail_df = None
        self.catalogs = {}

    def generate_interaction_logs(self, store_id="aura_threads", n_users=50, n_events=500):
        """
        Generates realistic interaction logs for training and temporal benchmarking.
        """
        catalog = self.get_catalog(store_id)
        pids = catalog['product_id'].tolist()
        categories = catalog['category'].tolist()
        
        users = [f"user_{i}" for i in range(1, n_users + 1)]
        events = ['view', 'click', 'add_to_cart', 'purchase']
        event_weights_map = {'view': 1.0, 'click': 1.5, 'add_to_cart': 4.0, 'purchase': 5.0}

        np.random.seed(42)
        rows = []
        now = datetime.now()

        for i in range(n_events):
            uid = np.random.choice(users)
            user_num = int(uid.split('_')[1])
            pref_cat = categories[user_num % len(categories)]
            
            matching_items = catalog[catalog['category'] == pref_cat]['product_id'].tolist()
            if matching_items and np.random.random() < 0.8:
                pid = np.random.choice(matching_items)
            else:
                pid = np.random.choice(pids)

            ev_type = np.random.choice(events, p=[0.5, 0.3, 0.15, 0.05])
            time_offset_hours = np.random.uniform(0, 168)
            ts = now - timedelta(hours=time_offset_hours)
            invoice_id = f"INV-{(i // 3) + 1}"

            rows.append({
                'invoice_id': invoice_id,
                'session_id': f"sess_{uid}_{i // 5}",
                'user_id': uid,
                'product_id': pid,
                'event_type': ev_type,
                'event_weight': event_weights_map[ev_type],
                'timestamp': ts
            })

        df = pd.DataFrame(rows).sort_values('timestamp')
        return df

